function checkDuplicateKeys(line) {
  let inString = false;
  let escapeNext = false;
  let braceStack = [];
  let currentKeySet = null;
  let currentRawKeySet = null;

  for (let i = 0; i < line.length; i++) {
    const ch = line[i];

    if (escapeNext) {
      escapeNext = false;
      continue;
    }

    if (ch === '\\') {
      escapeNext = true;
      continue;
    }

    if (ch === '"') {
      if (!inString) {
        inString = true;
      } else {
        // End of string literal
        inString = false;

        // Check if this string is a member name
        if (braceStack.length > 0 && currentKeySet !== null) {
          // Look ahead for colon after optional whitespace
          let j = i + 1;
          while (j < line.length && /\s/.test(line[j])) {
            j++;
          }
          if (j < line.length && line[j] === ':') {
            // This is a member name
            try {
              const decoded = JSON.parse('"' + line.slice(0, i + 1) + '"');
              if (currentKeySet.has(decoded)) {
                return { hasDuplicate: true };
              }
              currentKeySet.add(decoded);
            } catch (e) {
              // Use raw escaped text
              const rawText = line.slice(0, i + 1);
              if (currentRawKeySet.has(rawText)) {
                return { hasDuplicate: true };
              }
              currentRawKeySet.add(rawText);
            }
          }
        }
      }
      continue;
    }

    if (inString) {
      continue;
    }

    if (ch === '{') {
      braceStack.push('object');
      currentKeySet = new Set();
      currentRawKeySet = new Set();
    } else if (ch === '[') {
      braceStack.push('array');
      currentKeySet = null;
      currentRawKeySet = null;
    } else if (ch === '}' || ch === ']') {
      if (braceStack.length === 0) {
        // Unmatched closing, but don't throw
        continue;
      }
      const top = braceStack.pop();
      if (top === 'object') {
        currentKeySet = null;
        currentRawKeySet = null;
      }
    }
  }

  return { hasDuplicate: false };
}

export function expectedMatrixFor(runtime) {
  if (runtime === null || typeof runtime !== 'object' || Array.isArray(runtime)) {
    throw new TypeError('runtime must be a non-null object');
  }

  const childPid = runtime.childPid;
  const servicePid = runtime.servicePid;

  if (!Number.isSafeInteger(childPid) || childPid <= 0) {
    throw new TypeError('runtime.childPid must be a positive safe integer');
  }

  if (!Number.isSafeInteger(servicePid) || servicePid <= 0) {
    throw new TypeError('runtime.servicePid must be a positive safe integer');
  }

  return [
    { operation: 'own-write', expectedOutcome: 'ALLOWED', expectedErrno: 0 },
    { operation: 'own-read', expectedOutcome: 'ALLOWED', expectedErrno: 0 },
    { operation: 'outside-read', expectedOutcome: 'DENIED', expectedErrno: 1 },
    { operation: 'loopback-bind', expectedOutcome: 'DENIED', expectedErrno: 1 },
    { operation: 'self-report', expectedOutcome: 'SELF_REPORT', expectedPid: childPid, expectedPpid: servicePid }
  ];
}
